#!/usr/bin/env python3
"""Prototype of the L1.1 column-level dangling-reader detector."""
import ast, re, sys, sqlite3, pathlib

DB = sys.argv[1]
ROOTS = sys.argv[2:] or ['scripts', 'schemas', 'tools']
con = sqlite3.connect('file:%s?mode=ro' % DB, uri=True)
SCHEMA = {}
for (n, t) in con.execute("select name,type from sqlite_master where type in ('table','view')"):
    SCHEMA[n] = {r[1] for r in con.execute('PRAGMA table_info("%s")' % n)}

SQL_EXEC = {"execute", "executemany", "executescript"}
KW = set("""select from where and or not in is null as join left right inner outer on group by order
having limit offset union all distinct case when then else end asc desc count sum min max avg coalesce
insert into values update set delete replace exists like between cast integer text real create table
view if index unique primary key references default check on conflict ignore substr lower upper
strftime date group_concat nullif abs round length trim ifnull with recursive over partition""".split())

def sql_of(call):
    """The concatenated constant parts of a .execute() first argument."""
    parts = []
    for s in ast.walk(call):
        if isinstance(s, ast.Constant) and isinstance(s.value, str):
            parts.append(s.value)
        elif isinstance(s, ast.FormattedValue):
            parts.append(" ? ")      # an interpolated hole is opaque; never a name
    return " ".join(parts)

TBL = re.compile(r'\b(?:FROM|JOIN|INTO|UPDATE)\s+["\[]?([A-Za-z_][A-Za-z0-9_]*)["\]]?(?:\s+(?:AS\s+)?([A-Za-z_][A-Za-z0-9_]*))?', re.I)
QUAL = re.compile(r'\b([A-Za-z_][A-Za-z0-9_]*)\.([A-Za-z_][A-Za-z0-9_]*)')
BARE = re.compile(r'\b([a-z_][a-z0-9_]*)\b')

findings = []
files = []
for root in ROOTS:
    files += [p for p in pathlib.Path(root).rglob('*.py') if '__pycache__' not in str(p)]
examined = 0
for p in files:
    try:
        tree = ast.parse(p.read_text(encoding='utf-8', errors='replace'))
    except SyntaxError:
        continue
    for node in ast.walk(tree):
        if not (isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute)
                and node.func.attr in SQL_EXEC and node.args):
            continue
        sql = sql_of(node.args[0])
        if not sql.strip():
            continue
        examined += 1
        alias = {}
        tables = []
        for m in TBL.finditer(sql):
            t, a = m.group(1), m.group(2)
            if t in SCHEMA:
                tables.append(t)
                alias[t] = t
                if a and a.lower() not in KW:
                    alias[a] = t
        if not tables:
            continue
        for m in QUAL.finditer(sql):
            q, c = m.group(1), m.group(2)
            if q in alias and c not in SCHEMA[alias[q]] and c != '*':
                findings.append((str(p), node.lineno, alias[q], c, 'qualified'))
        if len(set(tables)) == 1:
            t = tables[0]
            known = SCHEMA[t]
            for m in BARE.finditer(sql):
                w = m.group(1)
                if w in KW or w in known or w in alias:
                    continue
                # only flag words that look like a column reference: adjacent to
                # SELECT-list / WHERE / SET punctuation, and present in NO table.
                if any(w in cs for cs in SCHEMA.values()):
                    findings.append((str(p), node.lineno, t, w, 'bare-in-other-table'))
print("EXAMINED: %d executed SQL statements in %d files" % (examined, len(files)))
seen = set()
for f in findings:
    k = (f[0], f[1], f[2], f[3])
    if k in seen: continue
    seen.add(k)
    print("  DANGLING %-48s %s.%s   (%s)" % (f[0] + ':' + str(f[1]), f[2], f[3], f[4]))
print("total distinct: %d" % len(seen))
