view if index unique primary key references default check conflict ignore substr lower upper json
strftime date group_concat nullif abs round length trim ifnull with recursive over partition using
begin commit rollback pragma drop alter add column temp temporary autoincrement collate nocase
""".split())
CMT=re.compile(r'--[^\n]*|/\*.*?\*/',re.S)
