QUAL=re.compile(r'\b([A-Za-z_]\w*)\.([A-Za-z_]\w*)')
BARE=re.compile(r'\b([a-z_][a-z0-9_]*)\b')
ALIAS_AS=re.compile(r'\bAS\s+["\[]?([A-Za-z_]\w*)',re.I)

def consts(node):
    out=[]
    for s in ast.walk(node):
        if isinstance(s,ast.Constant) and isinstance(s.value,str): out.append(s.value)
        elif isinstance(s,ast.FormattedValue): out.append(" ? ")
    return " ".join(out)

findings=[]; examined=0; files=[]
for root in ROOTS: files+= [p for p in pathlib.Path(root).rglob('*.py') if '__pycache__' not in str(p)]
for p in files:
    src=p.read_text(errors='replace')
    try: tree=ast.parse(src)
    except SyntaxError: continue
    # 1. constant-propagate module/function-local single-assignment string names
    env={}
    for n in ast.walk(tree):
